def lebesgueLpLocalize (s : Set α) (hs : MeasurableSet s) : Lp E p μ →L[𝕜] Lp E p μ :=
  (lebesgueLpExtend (𝕜 := 𝕜) s hs).toContinuousLinearMap.comp
    (lebesgueLpRestrict (𝕜 := 𝕜) s)

