  (lebesgueLpLocalize (𝕜 := 𝕜) (lpHaarCell n k) measurableSet_Ioc).comp
    (ContinuousLinearMap.id 𝕜 (IntervalLp 𝕜 q) - lpHaarDyadicMean 𝕜 q hq n)

